const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);      // Window Size
p.colorMode(p.RGB, 1.0); // RGB(0.0~1.0)
var fR, fG, fB;      // Window RGB
for (var iX=0; iX<p.width; iX++)
{
  for (var iY=0; iY<p.height; iY++)
  {
    /* Example */
    fR =  1.0/((p.pow(iX-250, 2)/iY+p.pow(iY-100, 2)/iY)/50.0)+0.5 - (90+p.pow(1.1, iY*0.1)*p.cos(p.radians(10*iY))*8)/125;
    fG =  1.0/((p.pow(iX-250, 2)/iY+p.pow(iY-100, 2)/iY)/50.0)+0.5 - (90+p.pow(1.1, iY*0.1)*p.cos(p.radians(10*iY))*8)/125;
    fB =  p.sin(p.random(100));

    // draw pixel
    p.stroke(fR, fG, fB);
    p.point(iX, iY);
  }
}

  };
};

export default sketch;
