const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.background(0);

var x=0;
var y=0;

for (var iX=0; iX<100 && iX<100; iX++)
{
  x=x+6;
  y=y+5;
  p5obj.stroke(10, x+100, y+200, 150);
  p5obj.noFill();
  p5obj.ellipse(x, y, x-400, y+50);
}

x=0;
y=100;
for (var iY=0; iY<100 && iY<100; iY++)
{
  x=x+4;
  y=y+6;
  p5obj.stroke(10, x+100, y+200, 150);
  p5obj.noFill();
  p5obj.ellipse(x, y, x+180, y-200);
}

  };
};

export default sketch;
