const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);      // Window Size
p.colorMode(p.RGB, 1.0); // RGB(0.0~1.0)
var fR, fG, fB;      // Window RGB
for (var iX=0; iX<p.width; iX++)
{
  for (var iY=0; iY<p.height; iY++)
  {
    fR = p.pow(p.sin(iX/20.0), 2) * p.cos(iY/20.0) * 0.5 + 0.5;
    fG = p.pow(p.sin(iX/15.0), 2) * p.cos(iY/15.0) * 0.5 + 0.5;
    fB = p.pow(p.sin(iX/10.0 + iY/20.0), 2) * p.cos(iY/10.0) * 0.5 + 0.5;

    // draw pixel
    p.stroke(fR, fG, fB);
    p.point(iX, iY);
  }
}

  };
};

export default sketch;
